def average_checkpoints(paths, out_path="swa_model.safetensors"):
    avg = None
    for p in paths:
        state = torch.load(p, map_location="cpu", weights_only=False)["state_dict"]
        if avg is None:
            avg = {k: v.clone().float() for k, v in state.items()}
        else:
            for k in avg:
                avg[k] += state[k].float()
    avg = {k: v / len(paths) for k, v in avg.items()}
    save_file(avg, out_path)
    return out_path

