def aggregate_round(global_model, updates_from_devices):
    new_state = {}
    for key, value in global_model.state_dict().items():
        stacked = torch.stack([u[key].float() for u in updates_from_devices])
        new_state[key] = value.float() + stacked.mean(dim=0)
    global_model.load_state_dict(new_state)
    return global_model

