MAX_UPDATE_NORM = 5.0

def aggregate_round(global_model, updates_from_devices):
    accepted = []
    for u in updates_from_devices:
        if not verify_device_attestation(u.device_id, u.signature):
            continue
        norm = float(torch.sqrt(sum((t.float() ** 2).sum() for t in u.delta.values())))
        scale = min(1.0, MAX_UPDATE_NORM / (norm + 1e-12))
        accepted.append({k: t.float() * scale for k, t in u.delta.items()})
    if len(accepted) < MIN_CLIENTS:
        return global_model
    new_state = {k: v.float() + torch.stack([a[k] for a in accepted]).median(dim=0).values
                 for k, v in global_model.state_dict().items()}
    global_model.load_state_dict(new_state)
    return global_model

